const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

function makeSource({ values = [], readError, closeError, openError } = {}) {
  const log = { opens: 0, reads: 0, closes: 0 };
  const queue = [...values];
  const source = {
    open: async () => {
      if (openError) throw openError;
      log.opens++;
      return {
        read: async () => {
          log.reads++;
          if (readError && log.reads === readError.at) throw readError.err;
          return queue.length ? queue.shift() : null;
        },
        close: async () => { log.closes++; if (closeError) throw closeError; },
      };
    },
  };
  return { source, log };
}
const rejects = async (p, err) => { try { await p; } catch (e) { assert.equal(e, err); return; } assert.fail('expected rejection'); };

async function main() {
  // Unopened generator: return() must not open or close.
  { const { source, log } = makeSource({ values: ['a'] });
    const g = new EventService(source).stream();
    assert.deepEqual(await g.return(undefined), { value: undefined, done: true });
    assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 });
    const g2 = new EventService(source).stream(); // never iterated
    assert.equal(log.opens, 0); }

  // Lazy open and no read-ahead; exhaustion closes once.
  { const { source, log } = makeSource({ values: ['a', 'b'] });
    const g = new EventService(source, (v) => v + '!').stream();
    assert.equal(log.opens, 0);
    assert.deepEqual(await g.next(), { value: 'a!', done: false });
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 0 });
    assert.deepEqual(await g.next(), { value: 'b!', done: false });
    assert.deepEqual(log, { opens: 1, reads: 2, closes: 0 });
    assert.deepEqual(await g.next(), { value: undefined, done: true });
    assert.deepEqual(log, { opens: 1, reads: 3, closes: 1 });
    await g.next(); assert.equal(log.closes, 1); }

  // Consumer break.
  { const { source, log } = makeSource({ values: ['a', 'b', 'c'] });
    for await (const v of new EventService(source).stream()) { assert.equal(v, 'A'); break; }
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 }); }

  // Break with close failure propagates the close failure.
  { const ce = new Error('close');
    const { source, log } = makeSource({ values: ['a', 'b'], closeError: ce });
    await rejects((async () => { for await (const _ of new EventService(source).stream()) break; })(), ce);
    assert.equal(log.closes, 1); }

  // Exhaustion with close failure propagates the close failure.
  { const ce = new Error('close');
    const { source, log } = makeSource({ values: ['a'], closeError: ce });
    await rejects((async () => { for await (const _ of new EventService(source).stream()); })(), ce);
    assert.equal(log.closes, 1); }

  // Read failure: original preserved, even if close fails too.
  for (const closeError of [undefined, new Error('close')]) {
    const re = new Error('read');
    const { source, log } = makeSource({ values: ['a', 'b'], readError: { at: 2, err: re }, closeError });
    await rejects((async () => { for await (const _ of new EventService(source).stream()); })(), re);
    assert.equal(log.closes, 1); }

  // Mapper failure.
  for (const closeError of [undefined, new Error('close')]) {
    const me = new Error('map');
    const { source, log } = makeSource({ values: ['a', 'b'], closeError });
    const svc = new EventService(source, () => { throw me; });
    await rejects((async () => { for await (const _ of svc.stream()); })(), me);
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 }); }

  // Injected throw.
  for (const closeError of [undefined, new Error('close')]) {
    const te = new Error('thrown in');
    const { source, log } = makeSource({ values: ['a', 'b'], closeError });
    const g = new EventService(source).stream();
    await g.next();
    await rejects(g.throw(te), te);
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
    assert.deepEqual(await g.next(), { value: undefined, done: true });
    assert.equal(log.closes, 1); }

  // Open failure: nothing to close.
  { const oe = new Error('open');
    const { source, log } = makeSource({ openError: oe });
    await rejects(new EventService(source).stream().next(), oe);
    assert.equal(log.closes, 0); }
}
module.exports = main();

