import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    // Nothing runs (and no lease is opened) until the first next() call.
    const lease = await this.source.open();
    let failed = false;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // Read, mapper or consumer-injected throw: remember it so that a
      // failing close() cannot replace it.
      failed = true;
      throw error;
    } finally {
      // Runs exactly once on exhaustion, break/return, and on errors.
      try {
        await lease.close();
      } catch (closeError) {
        if (!failed) throw closeError;
      }
    }
  }
}
